  import hussarRequest from '@/views/workflow/util/request'
import { workFlowApi } from "@/api/workflow/flow/workFlowApi";

export default {
  name: "FreeJumpDialog",
  props: {
    // 弹窗显隐标识
    freeJumpDialogVisible: {
      type:Boolean,
      default:false,
    },
    // 参与者弹窗操作类型
    assigneeConfigType: {
      type:String,
      default:'add',
    },
    // 选择节点列表
    nextNodeOptions: {
      type:Array,
      default:()=>{
        return [];
      },
    },
    freeJumpDialogLoading: {
      type:Boolean,
      default:false,
    },
    dialogTitle: String
  },
  data() {
    return {
      // 表格加载层
      tableLoading: true,
      // 搜索内容
      searchContent: "",
      // 默认显示第几页
      currentPage: 1,
      // 默认每页显示的条数（可修改）
      PageSize: 10,
      // 选项
      selection: {},
      totalCount: 0,
      // 树数据
      treeData: [],
      treeKey: new Date() + "tree",
      // 人员树配置
      props: {
        id: "id",
        label: "label",
        children: "childrenList",
        isLeaf: "isLeaf",
      },
      // 用户名称和部门列表
      tableList: [],
      // 表格搜索条件
      tableItem: {},
      // 已选列表
      selectList: [],
      // 控制popover 显隐
      visible: false,
      // 搜索内容
      inputSelect: "",
      filterText: "",
      //人员名称和组织数组
      options: [],
      isbg: false,
      // 多选选项
      multipleSelection: [],
      // 选中节点
      nextNodeValue: '',
    };
  },
  computed: {},
  watch: {
    // 监控页面显隐
    freeJumpDialogVisible: {
      handler(n) {
        if (n) {
          this.searchContent = "";
          this.treeKey = new Date() + "tree";
          this.visible = false;
          this.selection = {};
          this.tableItem = {};
          if (this.nextNodeOptions.length > 0) {
            this.nextNodeValue = this.nextNodeOptions[0].id;
          }
          this.getTableList({});
        }
      },
      deep: true,
    },
    // 过滤树节点
    filterText: {
      handler(n) {
        this.currentPage = 1;
        if (n === "") {
          this.visible = false;
          this.options = [];
          this.treeData = [];
          this.tableList = [];
          this.tableItem = {};
          this.getTableList();
        } else {
          // 选中的部门，表格显示部门内的人员，刷新树
          // 选中的人员，表格显示选中的人员，刷新树
          this.tableItem = n;
          this.getTableList(n);
          hussarRequest.get(workFlowApi.queryDeptTreeByChildren, { ...n }).then((res) => {
            if(res.code===10000){
              if(Object.keys(res.data).length !==0){
                this.treeData = [...res.data];
              }
            }
          });
        }
      },
      deep: true,
    },
    // 查询条件
    inputSelect: {
      handler(n) {
        if (n === "") {
          this.filterText = "";
        }
      },
      deep: true,
    },
    // 选项
    selection: {
      handler(n) {
        if (JSON.stringify(n) !== "{}" && n !== null) {
          this.selectList = [n];
        }
      },
      deep: true,
    },
    // 用户名称和部门列表
    tableList: {
      handler(n) {
        if (n.length) {
          const self = this;
          this.$nextTick(() => {
            self.$refs.multipleTable.clearSelection();
            self.selectList.forEach((item) => {
              n.findIndex((it) => {
                const index = it.id === item.id;
                if (index) {
                  self.$refs.multipleTable.toggleRowSelection(it, true);
                }
              });
            });
          });
        }
      },
      deep: true,
    },
  },
  methods: {
    // 确认
    confirmSelect() {
        let selectValue = [];
        this.selectList.forEach((element) => {
          selectValue.push(element.id);
        });
        this.$emit("confirm", {
          ids: selectValue.join(','),
          nextNodeValue: this.nextNodeValue,
        });
    },
    // 显示第几页
    handleCurrentChange(val) {
      // 改变默认的页数
      this.currentPage = val;
      this.getTableList();
    },
    // 关闭页面
    handleClose() {
      this.$emit("close");
      this.$nextTick(() => {
        this.treeData = [];
        this.currentPage = 1;
        this.tableList = [];
        this.options = [];
        this.visible = false;
        this.filterText = "";
        this.inputSelect = "";
        this.selectList = [];
        this.selection = {};
      });
    },
    // 懒加载树
    loadNode(node, resolve) {
      let id = "-1";
      if (node.level !== 0) {
        id = node.data.id;
      }
      const data = { id: id };
      hussarRequest
        .get(workFlowApi.dept, data)
        .then((res) => {
          if (res.code === 10000) {
            return resolve(res.data);
          } else {
            top.window.showErrorMessage("获取人员树异常");
          }
        })
        .catch((e) => {
          if (this.strategy) {
            top.window.showErrorMessage("获取人员树异常");
          } else {
            this.$message.error("获取人员树异常");
          }
        });
    },
    // 渲染树节点
    renderContent(h, { node, data }) {
      let iconType = "";
      if (node.level === 1) {
        iconType = "tree-com";
      } else if (node.level === 2) {
        iconType = "tree-department";
      } else {
        iconType = "unit";
      }
      return (
        <div class="tree-div">
          <span class="staff-tree">
            <span className="svg-icon">
              <svg-icon icon-class={iconType} />
            </span>
            {node.label}
          </span>
        </div>
      );
    },
    // 树节点点击
    handleNodeClick(item) {
      this.tableItem = item;
      this.getTableList(item);
    },
    // 清空已选
    delAllSelection() {
      this.$refs.multipleTable.clearSelection();
      this.selectList = [];
      this.selection = {};
    },
    // 获取焦点
    inpFocus() {
      this.isbg = true;
      if (this.options.length) {
        this.visible = true;
      }
    },
    // 搜索
    changeFilter() {
      this.enterMethod(this.inputSelect);
    },
    // 模糊查询树的下拉
    enterMethod(query) {
      this.visible = false;
      this.options = [];
      if (query !== "") {
        this.loading = true;
        hussarRequest
          .get(workFlowApi.queryUserTree, {
            organName: query,
          })
          .then((res) => {
            if (res.code === 10000) {
              this.loading = false;
              const user = [];
              const organ = [];
              res.data.forEach((item) => {
                if (item.type === "user") {
                  user.push(item);
                } else {
                  organ.push(item);
                }
              });
              this.options.push({
                label: `员工（${hussar-user.length}）`,
                options: [...user],
                show: false
              });
              this.options.push({
                label: `部门（${organ.length}）`,
                options: [...organ],
                show: false
              });
              if (res.data.length) {
                this.visible = true;
              }
            } else {
              // top.window.showErrorMessage('获取人员树异常');
            }
          })
          .catch((e) => {
            // this.$message.error('获取人员树异常');
          });
      } else {
        this.options = [];
      }
    },
    // 点击查询到的列表数据
    changeInput(item) {
      this.filterText = item;
      this.inputSelect = item.label;
      this.visible = false;
    },
    // 获取列表数据
    getTableList(n = this.tableItem) {
      this.tableList = [];
      hussarRequest
        .get(workFlowApi.queryUserListByPage, {
          ...{ ...n, ...{ childrenList: [] } },
          size: this.PageSize,
          current: this.currentPage,
        })
        .then((res) => {
          this.tableLoading = false;
          if (res.code === 10000) {
            this.tableList = [...res.data.records];
            this.totalCount = res.data.total;
          }
        });
    },
    // table多选
    handleSelectionChange(val) {
      this.multipleSelection = val;
      this.selectList = [...this.multipleSelection];
    },
    // 选择节点点击事件
    clickNodeList(item) {
      this.nextNodeValue = item.id;
      this.options = [];
      this.filterText = '';
      this.inputSelect = '';
      this.selectList = [];
      this.$refs.multipleTable.clearSelection();
    },
  },
};
